#include "lead_identity.hpp"
#include <iostream>
using namespace frenet;
int main(int argc,char**argv){try{Assets assets(argv[1]);auto config=json_read(argv[2]);LeadIdentity identity(assets,config["lead_identity_v1"]);std::string line;while(std::getline(std::cin,line)){Json::Value v;Json::Reader reader;if(!reader.parse(line,v))return 2;std::vector<Point> points;for(auto p:v["obstacle_points"])points.emplace_back(p[0].asDouble(),p[1].asDouble());auto pose=path_read(v["scan_pose"].isArray()&&v["scan_pose"][0].isNumeric()?Json::Value(Json::arrayValue):v["poses"]);Pose q;if(v["scan_pose"].size()==3)q={v["scan_pose"][0].asDouble(),v["scan_pose"][1].asDouble(),v["scan_pose"][2].asDouble()};else if(!pose.empty())q=pose[0];else throw std::runtime_error("pose_missing");Json::Value out;out["occupancies"]=identity.apply(v["occupancies"],points,q,v["source_scan_stamp"].asDouble());out["lead_identity"]=identity.status();out["physical_motion"]=false;std::cout<<dump(out)<<std::endl;}}catch(const std::exception& e){std::cerr<<e.what()<<std::endl;return 1;}}
